
(function($){'use strict';$(document).on('submit','.mpesa-stk-form',function(e){e.preventDefault();var $form=$(this);var $wrap=$form.closest('.mpesa-stk-wrap');var $status=$form.find('.mpesa-stk-status');var $button=$form.find('.mpesa-stk-submit');var phone=$form.find('[name="phone"]').val();var amount=$form.find('[name="amount"]').val();var reference=$wrap.data('reference')||'Payment';$button.prop('disabled',!0).text('Sending request...');$status.removeClass('is-error is-success').text('');$.post(MpesaStk.ajax_url,{action:'mpesa_stk_initiate',nonce:MpesaStk.nonce,phone:phone,amount:amount,reference:reference}).done(function(response){if(!response.success){$button.prop('disabled',!1).text('Pay Now');$status.addClass('is-error').text(response.data.message||'Something went wrong.');return}
$status.removeClass('is-error').addClass('is-success').text(response.data.message);$button.text('Waiting for confirmation...');pollStatus(response.data.checkout_request_id,$status,$button,$wrap)}).fail(function(){$button.prop('disabled',!1).text('Pay Now');$status.addClass('is-error').text('Network error. Please try again.')})});function pollStatus(checkoutRequestId,$status,$button,$wrap){var attempts=0;var maxAttempts=20;var interval=setInterval(function(){attempts++;$.post(MpesaStk.ajax_url,{action:'mpesa_stk_status',nonce:MpesaStk.nonce,checkout_request_id:checkoutRequestId}).done(function(response){if(!response.success){return}
var status=response.data.status;if(status==='completed'){clearInterval(interval);$status.removeClass('is-error').addClass('is-success').text('Payment received. Receipt: '+(response.data.mpesa_receipt||''));$button.text('Paid');redirectAfterSuccess($wrap)}else if(status==='failed'){clearInterval(interval);$status.removeClass('is-success').addClass('is-error').text(response.data.result_desc||'Payment was not completed.');$button.prop('disabled',!1).text('Try Again')}});if(attempts>=maxAttempts){clearInterval(interval);$status.text('Still waiting on confirmation. If you approved the prompt, this page will update shortly — you can also refresh.');$button.prop('disabled',!1).text('Pay Now')}},3000)}
function redirectAfterSuccess($wrap){var perFormUrl=$wrap.data('redirect');var url=perFormUrl?perFormUrl:MpesaStk.redirect_url;if(!url){return}
var delay=(typeof MpesaStk.redirect_delay!=='undefined')?parseInt(MpesaStk.redirect_delay,10):2;setTimeout(function(){window.location.href=url},delay*1000)}})(jQuery);


